#define sat clamp01
float z, z0, radi, radi0, kk;
vec2 uv1, uv2;
vec3 rs;
const int anz = 30;
const float ir0 = 4, scale=1.8;
vec3 Get1 (vec2 uvi)
{return GetBlur1(uvi);}
vec3 argo (vec2 uvi)
{
float k1 = sqrt(abs(q6-ir0*ir0*uvi.y*uvi.y));
float k2 = 1.0 / k1;  kk = k2;
k1 = mix(k1,k2,q5);
vec2 rs = vec2 (asin(uvi.x*ir0/k1) * 2.0/M_PI, (uvi.y*ir0/k1))/scale;
return (0.5*vec3 (rs,ir0*length(rs)>2)) * 2.0;
}
shine = clamp01(shine*2.1/anz-0.1);
shine = mix(shine, vec3(lum(shine)), 0.0 * clamp01(q14 / 3.0));
ret = shine + struc;
uv2 = vec2 (uv1.x*0.25+0.5,0.5+0.2*uv1.y);
ret = max(ret,clamp01(2-2*ir0/kk)*q15*(2.0 * GetBlur1(uv2)+0.1)) ;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec2 uv0 = uv;
uv = (uv-0.5)*(1.0 + rad*rad*0.5)*0.8+0.5;
uv1 = multiply((uv-0.5)*uAspect.xy,mat2(q8,q9,-q9,q8));
rs = argo(uv1)+0.5;
vec3 struc = GetPixel(rs) * clamp01(ir0/kk - 0.0);
//struc = pow(struc,0.8);
vec3 shine = struc * 0.0;
radi0 = ir0/scale*uAspect.x/uAspect.y*0.7*mix(1.0 / sqrt(q6), pow(q6,0.3),q5);
radi = radi0;
for (int n=0; n < anz; n++)
{
radi = (1.0 - (1.0*n/anz) ) * radi0;;
shine += Get1(uv1*uAspect.yx*radi+0.5);
  fragColor = vec4(ret, 1.0);
}

